import { useState, useMemo, useEffect, useCallback } from 'react';
import { motion } from 'framer-motion';
import {
  BarChart3,
  Eye,
  Users,
  CalendarClock,
  TrendingUp,
  LineChart,
  ExternalLink,
  Settings,
  Activity,
  Info,
  HardDrive,
  Trash2,
  AlertTriangle,
  RefreshCw,
} from 'lucide-react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle, CardFooter } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Switch } from '@/components/ui/switch';
import { Label } from '@/components/ui/label';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  DialogClose,
} from '@/components/ui/dialog';
import { useI18n } from '@/i18n/I18nContext';
import { logger } from '@lark-apaas/client-toolkit-lite';
import { useAnalytics, type AnalyticsStats } from '@/hooks/useAnalytics';
import { useAnalyticsSettings } from '@/hooks/useAnalyticsSettings';
import { applyAnalyticsScripts } from '@/lib/analytics-injector';
import { useInquiries } from '@/hooks/useInquiries';
import { toast } from 'sonner';
import PageBreadcrumb from '@/components/PageBreadcrumb';
import { format } from 'date-fns';
import {
  estimateStorageSize,
  clearUnnecessaryData,
  type StorageUsage,
} from '@/lib/storage-utils';

function formatDateTime(ts: number | null, adminLanguage: string): string {
  if (!ts) return '—';
  try {
    return format(ts, 'yyyy-MM-dd HH:mm');
  } catch {
    return new Date(ts).toLocaleString();
  }
}

export default function AdminAnalyticsPage() {
  const { adminT, adminLanguage } = useI18n();
  const { stats } = useAnalytics();
  const { settings, updateSettings } = useAnalyticsSettings();
  const { totalCount: inquiryTotal, inquiries } = useInquiries();

  const [form, setForm] = useState(() => ({ ...settings }));
  const [saving, setSaving] = useState(false);
  const [storageUsage, setStorageUsage] = useState<StorageUsage | null>(null);
  const [clearDialogOpen, setClearDialogOpen] = useState(false);
  const [clearing, setClearing] = useState(false);

  // 刷新存储用量
  const refreshStorageUsage = useCallback(() => {
    try {
      setStorageUsage(estimateStorageSize());
    } catch {
      setStorageUsage(null);
    }
  }, []);

  useEffect(() => {
    refreshStorageUsage();
  }, [refreshStorageUsage]);

  const handleSave = () => {
    setSaving(true);
    try {
      // 1. 保存到 localStorage（核心操作）
      const result = updateSettings(form);
      if (!result.success) {
        if (result.errorType === 'quota') {
          // 配额超限：友好提示 + 提供清理操作
          toast.error(
            <div className="space-y-2">
              <div className="font-medium">{adminT('admin.quotaExceededTitle')}</div>
              <div className="text-sm opacity-90">{adminT('admin.quotaExceededDesc')}</div>
              <Button
                size="sm"
                variant="secondary"
                onClick={() => {
                  handleClearCacheAndSave();
                }}
              >
                <RefreshCw className="size-3.5 mr-1" />
                {adminT('admin.quotaExceededAction')}
              </Button>
            </div>,
            { duration: 8000 },
          );
        } else {
          toast.error(adminT('admin.analyticsSaveFailed') + (result.errorMessage ? `: ${result.errorMessage}` : ''));
        }
        setSaving(false);
        return;
      }

      // 2. 立即应用脚本（动态注入/移除）—— 脚本注入失败不影响本地保存
      try {
        applyAnalyticsScripts(form);
      } catch (injectErr) {
        logger.warn('[AdminAnalytics] Script injection warning: ' + String(injectErr));
      }

      toast.success(adminT('admin.analyticsSaved'));
      refreshStorageUsage();
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      toast.error(adminT('admin.analyticsSaveFailed') + (msg ? ` (${msg})` : ''));
    } finally {
      setSaving(false);
    }
  };

  const handleClearCache = async () => {
    setClearing(true);
    try {
      await new Promise((r) => setTimeout(r, 400));
      const result = clearUnnecessaryData();
      toast.success(adminT('admin.clearStorageCacheSuccess').replace('{size}', result.freedFormatted));
      refreshStorageUsage();
      setClearDialogOpen(false);
    } finally {
      setClearing(false);
    }
  };

  const handleClearCacheAndSave = async () => {
    setClearing(true);
    try {
      await new Promise((r) => setTimeout(r, 400));
      const result = clearUnnecessaryData();
      logger.info('[AdminAnalytics] Cache cleared, freed ' + result.freedFormatted);
      refreshStorageUsage();
      // 清理后重试保存
      const saveResult = updateSettings(form);
      if (saveResult.success) {
        try { applyAnalyticsScripts(form); } catch { /* ignore */ }
        toast.success(adminT('admin.analyticsSaved'));
      } else {
        toast.error(adminT('admin.analyticsSaveFailed') + (saveResult.errorMessage ? `: ${saveResult.errorMessage}` : ''));
      }
    } finally {
      setClearing(false);
    }
  };

  // 今日 / 本周 询盘数
  const { todayInquiries, weekInquiries, lastInquiryTime } = useMemo(() => {
    const now = Date.now();
    const todayStart = new Date();
    todayStart.setHours(0, 0, 0, 0);
    const weekStart = new Date();
    weekStart.setDate(weekStart.getDate() - 7);
    weekStart.setHours(0, 0, 0, 0);

    let today = 0;
    let week = 0;
    let last: number | null = null;
    inquiries.forEach((inq) => {
      if (inq.createdAt >= todayStart.getTime()) today++;
      if (inq.createdAt >= weekStart.getTime()) week++;
      if (!last || inq.createdAt > last) last = inq.createdAt;
    });
    return { todayInquiries: today, weekInquiries: week, lastInquiryTime: last };
  }, [inquiries]);

  return (
    <div className="space-y-6">
      <PageBreadcrumb
        items={[{ label: adminT('admin.analytics'), href: '/admin/analytics' }]}
        firstItem={{ label: adminT('admin.dashboard'), href: '/admin/dashboard', icon: 'dashboard' }}
      />

      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-foreground">{adminT('admin.analytics')}</h1>
          <p className="text-sm text-muted-foreground mt-1">
            {adminT('admin.analyticsDesc')}
          </p>
        </div>
      </div>

      {/* 本地统计提示 */}
      <Alert className="bg-primary/5 border-primary/20">
        <Info className="h-4 w-4 text-primary" />
        <AlertTitle className="text-foreground font-medium">
          {adminT('admin.localStatsMode')}
        </AlertTitle>
        <AlertDescription className="text-muted-foreground text-sm">
          {adminT('admin.analyticsLocalNote')}
        </AlertDescription>
      </Alert>

      {/* KPI 统计卡片 */}
      <KpiRow stats={stats} inquiryTotal={inquiryTotal} todayInquiries={todayInquiries} lastInquiryTime={lastInquiryTime} adminT={adminT} adminLanguage={adminLanguage} />

      {/* 图表区：趋势 + 热门页面 */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <TrafficChart stats={stats} adminT={adminT} />
        <TopPagesTable stats={stats} adminT={adminT} />
      </div>

      {/* 配置区 */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* GA4 设置 */}
        <Card className="border-border/40 bg-card">
          <CardHeader>
            <div className="flex items-center justify-between">
              <div>
                <CardTitle className="text-base flex items-center gap-2">
                  <BarChart3 className="size-4 text-primary" />
                  {adminT('admin.ga4Title')}
                </CardTitle>
                <CardDescription className="mt-1">
                  {adminT('admin.ga4Desc')}
                </CardDescription>
              </div>
              <Badge variant={form.gaEnabled ? 'default' : 'outline'} className="text-[10px]">
                {form.gaEnabled ? 'ON' : 'OFF'}
              </Badge>
            </div>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label htmlFor="ga-enabled">{adminT('admin.ga4Enabled')}</Label>
              </div>
              <Switch
                id="ga-enabled"
                checked={form.gaEnabled}
                onCheckedChange={(v) => setForm((p) => ({ ...p, gaEnabled: v }))}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="ga-id">{adminT('admin.ga4IdLabel')}</Label>
              <Input
                id="ga-id"
                value={form.gaMeasurementId}
                onChange={(e) => setForm((p) => ({ ...p, gaMeasurementId: e.target.value }))}
                placeholder={adminT('admin.ga4IdPlaceholder')}
              />
              <p className="text-xs text-muted-foreground">
                {adminT('admin.ga4IdHint')}
              </p>
            </div>
            <Button
              variant="outline"
              size="sm"
              className="w-full gap-2"
              onClick={() => window.open('https://analytics.google.com/', '_blank', 'noopener,noreferrer')}
              disabled={!settings.gaEnabled || !settings.gaMeasurementId}
            >
              <ExternalLink className="size-3.5" />
              {adminT('admin.viewGaReport')}
            </Button>
          </CardContent>
        </Card>

        {/* Clarity 设置 */}
        <Card className="border-border/40 bg-card">
          <CardHeader>
            <div className="flex items-center justify-between">
              <div>
                <CardTitle className="text-base flex items-center gap-2">
                  <Activity className="size-4 text-primary" />
                  {adminT('admin.clarityTitle')}
                </CardTitle>
                <CardDescription className="mt-1">
                  {adminT('admin.clarityDesc')}
                </CardDescription>
              </div>
              <Badge variant={form.clarityEnabled ? 'default' : 'outline'} className="text-[10px]">
                {form.clarityEnabled ? 'ON' : 'OFF'}
              </Badge>
            </div>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label htmlFor="clarity-enabled">{adminT('admin.clarityEnabled')}</Label>
              </div>
              <Switch
                id="clarity-enabled"
                checked={form.clarityEnabled}
                onCheckedChange={(v) => setForm((p) => ({ ...p, clarityEnabled: v }))}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="clarity-id">{adminT('admin.clarityIdLabel')}</Label>
              <Input
                id="clarity-id"
                value={form.clarityProjectId}
                onChange={(e) => setForm((p) => ({ ...p, clarityProjectId: e.target.value }))}
                placeholder={adminT('admin.clarityIdPlaceholder')}
              />
              <p className="text-xs text-muted-foreground">
                {adminT('admin.clarityIdHint')}
              </p>
            </div>
            <Button
              variant="outline"
              size="sm"
              className="w-full gap-2"
              onClick={() => window.open('https://clarity.microsoft.com/', '_blank', 'noopener,noreferrer')}
              disabled={!settings.clarityEnabled || !settings.clarityProjectId}
            >
              <ExternalLink className="size-3.5" />
              {adminT('admin.viewClarityReport')}
            </Button>
          </CardContent>
        </Card>
      </div>

      {/* 保存按钮 */}
      <div className="flex justify-end">
        <Button onClick={handleSave} disabled={saving}>
          <Settings className="size-4 mr-2" />
          {saving ? 'Saving...' : adminT('admin.save')}
        </Button>
      </div>

      {/* 存储使用情况 */}
      <StorageUsageCard
        usage={storageUsage}
        adminT={adminT}
        onRefresh={refreshStorageUsage}
        onClear={() => setClearDialogOpen(true)}
      />

      {/* 清理缓存确认对话框 */}
      <Dialog open={clearDialogOpen} onOpenChange={setClearDialogOpen}>
        <DialogContent className="border-border/40 bg-card text-foreground">
          <DialogHeader>
            <DialogTitle>{adminT('admin.clearStorageCacheConfirm')}</DialogTitle>
            <DialogDescription className="text-muted-foreground">
              {adminT('admin.clearStorageCacheConfirmDesc')}
            </DialogDescription>
          </DialogHeader>
          {storageUsage && (
            <div className="py-2 space-y-2">
              <div className="flex justify-between text-sm">
                <span className="text-muted-foreground">{adminT('admin.storageUsed')}</span>
                <span className="font-medium tabular-nums">{storageUsage.usedFormatted}</span>
              </div>
              <Progress value={storageUsage.percent} className="h-2" />
            </div>
          )}
          <DialogFooter className="gap-2">
            <DialogClose asChild>
              <Button variant="outline">Cancel</Button>
            </DialogClose>
            <Button onClick={handleClearCache} disabled={clearing}>
              <Trash2 className="size-4 mr-2" />
              {clearing ? 'Clearing...' : adminT('admin.clearStorageCache')}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

function StorageUsageCard({
  usage,
  adminT,
  onRefresh,
  onClear,
}: {
  usage: StorageUsage | null;
  adminT: (k: string) => string;
  onRefresh: () => void;
  onClear: () => void;
}) {
  if (!usage) return null;

  const isNearFull = usage.percent > 80;

  return (
    <Card className="border-border/40 bg-card">
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <HardDrive className="size-4 text-primary" />
            <CardTitle className="text-base">{adminT('admin.storageUsage')}</CardTitle>
          </div>
          <Badge variant={isNearFull ? 'destructive' : 'outline'} className="text-[10px]">
            {isNearFull ? adminT('admin.storageQuotaFull') : `${usage.percent.toFixed(0)}%`}
          </Badge>
        </div>
        <CardDescription className="mt-1">
          {adminT('admin.storageUsageDesc')}
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* 进度条 */}
        <div className="space-y-2">
          <div className="flex justify-between text-sm">
            <span className="text-muted-foreground">{adminT('admin.storageUsed')}</span>
            <span className="font-medium tabular-nums">
              {usage.usedFormatted} / {usage.totalFormatted}
            </span>
          </div>
          <Progress value={usage.percent} className="h-2" />
          <div className="flex justify-between text-xs text-muted-foreground">
            <span>{adminT('admin.storageAvailable')}: {usage.availableFormatted}</span>
          </div>
        </div>

        {/* 占用 Top 5 */}
        <div>
          <div className="text-sm font-medium mb-2">{adminT('admin.topStorageItems')}</div>
          <div className="space-y-1.5">
            {usage.keys.slice(0, 5).map((k) => (
              <div key={k.key} className="flex items-center justify-between text-xs">
                <span className="text-muted-foreground truncate max-w-[240px]" title={k.key}>
                  {k.key.replace(/^_+miaoda_+global_+_+/, '').replace(/^__app_ledlight_/, '')}
                </span>
                <span className="tabular-nums shrink-0">{k.sizeFormatted}</span>
              </div>
            ))}
          </div>
        </div>
      </CardContent>
      <CardFooter className="flex gap-2 pt-2">
        <Button variant="outline" size="sm" onClick={onRefresh} className="gap-2">
          <RefreshCw className="size-3.5" />
          Refresh
        </Button>
        <Button size="sm" onClick={onClear} className="gap-2">
          <Trash2 className="size-3.5" />
          {adminT('admin.clearStorageCache')}
        </Button>
      </CardFooter>
    </Card>
  );
}

function KpiRow({
  stats,
  inquiryTotal,
  todayInquiries,
  lastInquiryTime,
  adminT,
  adminLanguage,
}: {
  stats: AnalyticsStats;
  inquiryTotal: number;
  todayInquiries: number;
  lastInquiryTime: number | null;
  adminT: (k: string) => string;
  adminLanguage: string;
}) {
  const kpis = [
    {
      label: adminT('admin.totalPV'),
      value: stats.totalPV.toLocaleString(),
      icon: Eye,
      sub: adminT('admin.localStatsMode'),
      color: 'text-primary',
      bg: 'bg-primary/10',
    },
    {
      label: adminT('admin.todayPV'),
      value: stats.todayPV.toLocaleString(),
      icon: CalendarClock,
      sub: adminT('admin.singleVisitorNote'),
      color: 'text-chart-2',
      bg: 'bg-chart-2/10',
    },
    {
      label: adminT('admin.uniqueVisitors'),
      value: '1',
      icon: Users,
      sub: adminT('admin.localStatsMode'),
      color: 'text-chart-3',
      bg: 'bg-chart-3/10',
    },
    {
      label: adminT('admin.inquiries'),
      value: inquiryTotal.toLocaleString(),
      icon: TrendingUp,
      sub: `${adminT('admin.todayPV').replace(/s Page Views$|s Vistas$|今日のページビュー$|今日访问量$/, '')}${todayInquiries} · ${adminT('admin.lastVisit')}: ${formatDateTime(lastInquiryTime, adminLanguage)}`.slice(0, 40),
      color: 'text-chart-4',
      bg: 'bg-chart-4/10',
    },
  ];

  return (
    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
      {kpis.map((kpi, idx) => {
        const Icon = kpi.icon;
        return (
          <motion.div
            key={kpi.label}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.4, delay: idx * 0.05 }}
          >
            <Card className="border-border/40 bg-card h-full">
              <CardContent className="p-5">
                <div className="flex items-center justify-between mb-3">
                  <div className={`w-10 h-10 rounded-lg ${kpi.bg} flex items-center justify-center`}>
                    <Icon className={`size-5 ${kpi.color}`} />
                  </div>
                </div>
                <div className="text-2xl font-bold text-foreground mb-1 tabular-nums">{kpi.value}</div>
                <div className="text-xs text-muted-foreground">{kpi.label}</div>
                <div className="text-[10px] text-muted-foreground/80 mt-2 line-clamp-1">{kpi.sub}</div>
              </CardContent>
            </Card>
          </motion.div>
        );
      })}
    </div>
  );
}

function TrafficChart({ stats, adminT }: { stats: AnalyticsStats; adminT: (k: string) => string }) {
  const max = Math.max(1, ...stats.dailyTrend.map((d) => d.count));

  return (
    <Card className="lg:col-span-2 border-border/40 bg-card">
      <CardHeader className="pb-2">
        <CardTitle className="text-base flex items-center gap-2">
          <LineChart className="size-4 text-primary" />
          {adminT('admin.trafficTrend')} — {adminT('admin.last7Days')}
        </CardTitle>
      </CardHeader>
      <CardContent>
        {stats.dailyTrend.every((d) => d.count === 0) ? (
          <div className="py-12 text-center">
            <BarChart3 className="size-8 text-muted-foreground/30 mx-auto mb-3" />
            <p className="text-sm text-muted-foreground">{adminT('admin.noData')}</p>
            <p className="text-xs text-muted-foreground/70 mt-1">{adminT('admin.noDataDesc')}</p>
          </div>
        ) : (
          <div className="flex items-end gap-2 md:gap-3 h-48 pt-4">
            {stats.dailyTrend.map((d, i) => {
              const heightPct = (d.count / max) * 100;
              const dateLabel = d.date.slice(5); // MM-DD
              return (
                <div key={d.date} className="flex-1 flex flex-col items-center gap-2">
                  <div className="text-xs font-medium tabular-nums text-foreground/80">{d.count || 0}</div>
                  <div className="w-full flex-1 flex items-end">
                    <div
                      className="w-full bg-primary/80 rounded-t-sm transition-all duration-300"
                      style={{ height: `${heightPct}%`, minHeight: d.count > 0 ? '4px' : '2px', opacity: d.count > 0 ? 1 : 0.2 }}
                    />
                  </div>
                  <div className="text-[10px] text-muted-foreground tabular-nums">{dateLabel}</div>
                </div>
              );
            })}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

function TopPagesTable({ stats, adminT }: { stats: AnalyticsStats; adminT: (k: string) => string }) {
  const max = Math.max(1, ...stats.topPages.map((p) => p.count));

  return (
    <Card className="border-border/40 bg-card">
      <CardHeader className="pb-2">
        <CardTitle className="text-base flex items-center gap-2">
          <TrendingUp className="size-4 text-primary" />
          {adminT('admin.topPages')}
        </CardTitle>
      </CardHeader>
      <CardContent className="p-0">
        {stats.topPages.length === 0 ? (
          <div className="py-10 text-center">
            <p className="text-sm text-muted-foreground">{adminT('admin.noData')}</p>
          </div>
        ) : (
          <div className="divide-y divide-border/40">
            {stats.topPages.map((p, i) => (
              <div key={p.path} className="p-3">
                <div className="flex items-center justify-between mb-1.5">
                  <div className="flex items-center gap-2 min-w-0">
                    <span className="shrink-0 w-5 h-5 rounded-full bg-primary/10 text-primary text-[10px] font-bold flex items-center justify-center">
                      {i + 1}
                    </span>
                    <span className="text-sm font-medium text-foreground truncate">{p.path}</span>
                  </div>
                  <span className="shrink-0 text-sm tabular-nums text-foreground/80">
                    {p.count}
                  </span>
                </div>
                <div className="w-full h-1.5 bg-muted/30 rounded-full overflow-hidden">
                  <div
                    className="h-full bg-primary/70 rounded-full"
                    style={{ width: `${(p.count / max) * 100}%` }}
                  />
                </div>
              </div>
            ))}
          </div>
        )}
      </CardContent>
    </Card>
  );
}
